body.script:
//
  (function(){
    var root=document.getElementById('page-root');
    var appBase='https://cdn.jsdelivr.net/gh/taufx98/sykabelajar_3.0@gh-pages';
    var cacheBust=String(Date.now());
    window.SYKA_BLOGGER_CONFIG={
      appBase:appBase,
      supabaseUrl:'https://jrfogwueytiddnanetth.supabase.co',
      supabasePublishableKey:'sb_publishable_H3zjdAEE-ItQ08YRj8MieQ_kNMcsAHa',
      cloudinaryCloudName:'sykabelajar',
      cloudinaryUploadPreset:'sykabelajar_preset'
    };

    function normalizeDirectPath(){
      var path=window.location.pathname || '/';
      var clean=path.replace(/^\/+|\/+$/g,'');
      if(!clean || clean==='p'||clean==='search') return;
      var allowed=/^(login|register|home|feed|leaderboard|daily-tasks|awards|notifications|orders|admin(?:\/.*)?|organizer(?:\/.*)?|profile\/[^/]+(?:\/.*)?|lomba\/[^/]+(?:\/.*)?|verify\/[^/]+)$/i;
      if(allowed.test(clean) && !window.location.hash){
        var target='/#/'+clean;
        if(window.location.search) target+=window.location.search;
        window.location.replace(target);
      }
    }

    function addCss(url){
      return new Promise(function(resolve,reject){
        var link=document.createElement('link');
        link.rel='stylesheet';
        link.href=url;
        link.onload=resolve;
        link.onerror=function(){reject(new Error('CSS gagal dimuat: '+url));};
        document.head.appendChild(link);
      });
    }

    function addScript(url){
      return new Promise(function(resolve,reject){
        var script=document.createElement('script');
        script.type='module';
        script.src=url;
        script.onload=resolve;
        script.onerror=function(){reject(new Error('Bundle gagal dimuat: '+url));};
        document.body.appendChild(script);
      });
    }

    normalizeDirectPath();
    Promise.all([
      addCss(appBase+'/styles.min.css?v='+cacheBust),
      addScript(appBase+'/app.js?v='+cacheBust)
    ]).catch(function(error){
      console.error('[SykaBelajar] bundle load failed',error);
      root.innerHTML='<div class="blogger-noscript"><strong>SykaBelajar gagal dimuat.</strong><br/>Bundle terbaru dari GitHub Pages belum berhasil dimuat. Refresh halaman atau cek deployment GitHub Actions.</div>';
    });
  })();
  //
